  worker:
    command: ["python", "-m", "jobqueue.worker", "--queues", "critical,default,low", "--concurrency", "16"]
    deploy: {replicas: 3}
    stop_grace_period: 30s      # SIGTERM -> drain in-flight jobs before SIGKILL
    depends_on: {redis: {condition: service_healthy}, migrate: {condition: service_completed_successfully}}

# real: jobqueue/worker/worker.py
for qname in self.queues:          # strict priority: earlier queues drained first
    try:
        out += await self.q.claim_many(qname, self.id, n - len(out), max_lease_ms=self.max_lease_ms)
    except Exception:
        log.exception("claim_failed", extra={"queue": qname})
        await asyncio.sleep(0.5)
        return out
    if len(out) >= n:
        break

